    "requirement_statement": {
      "text": "",
      "statements": [
        {
          "modal": "Must",
          "text": "judge-jev MUST support the target mode `prompt`."
        },
        {
          "modal": "Must",
          "text": "judge-jev MUST support the target mode `skill`."
        },
        {
          "modal": "Must",
          "text": "judge-jev MUST support the target mode `task`."
        },
        {
          "modal": "Must",
          "text": "judge-jev MUST support the target mode `code`."
        },
        {
          "modal": "Must",
          "text": "In `task` mode judge-jev MUST judge the raw template."
        },
        {
          "modal": "Must",
          "text": "In `task` mode judge-jev MUST judge an assignment rendered by sc-compose\nin strict mode from the vars file that `--vars` names, or, in a profile\nrun, that the profile names."
        },
        {
          "modal": "Must",
          "text": "In `code` mode judge-jev MUST resolve the location with the tree-sitter\ngrammars sc-agent defines."
        },
        {
          "modal": "MustNot",
          "text": "judge-jev MUST NOT define its own tree-sitter grammars."
        }
      ]
    },
    "rationale": "The raw template shows which variables are substituted; a rendered\nassignment shows what an agent actually receives. Strict rendering fails on\na missing variable instead of judging a half-rendered assignment. sc-agent\nowns the grammars so every consumer selects code the same way.",
    "success_criteria": {
      "text": "",
      "acceptance_criteria": [
        {
          "text": "A task template checked in `task` mode produces one result for the\nraw template and one for its rendered assignment.",
          "checked": false
        },
        {
          "text": "A vars file missing a template variable fails the render with the\nvariable named.",
          "checked": false
        },
        {
          "text": "The repository contains no tree-sitter grammar definitions.",
          "checked": false
        }
